    String name;
    Person(String name) {
        this.name = name;
    }
}
class Employee extends Person {
    int employeeId;
    double salary;
    Employee( String name, int employeeId) {
        this(employeeId, name, 0);
    }
    Employee(int employeeId, String name, double salary) {
        this(name);
        this.employeeId = employeeId;
        this.salary = salary;
    }
